/* eslint-disable security/detect-object-injection -- Indices are generated by the surrounding map/loop and bounded by the texts/embeddings array length. */
import { embedMany, ensureModel } from "@/lib/ai/service";
import {
  buildTsCall,
  formatTsMethodCall,
  rawTs,
  recordAstraClientCall,
} from "@/lib/astraClientLog";
import { CSV_BATCH_SIZE } from "@/lib/ingest/constants";
import { validateVectorDimension } from "@/lib/knowledge/dataApi/collectionConfig";
import type { CreateDataApiDb, DataApiKnowledgeConfig } from "@/lib/knowledge/dataApi/config";
import { resolveDataApiIngestContext } from "@/lib/knowledge/dataApi/ingestContext";
import type { KnowledgeCsvIngestRequest } from "@/lib/knowledge/types";

export async function ingestCsvIntoDataApi(
  request: KnowledgeCsvIngestRequest,
  send: (event: Record<string, unknown>) => void,
  createDb: CreateDataApiDb,
  displayName: string
) {
  const { collection, rows, filename, huggingfaceApiKey } = request;
  const { collection: collectionRef, collectionConfig, backend, backendHint } =
    await resolveDataApiIngestContext({
      config: request.config as DataApiKnowledgeConfig,
      collectionName: collection,
      huggingfaceApiKey,
      createDb,
      displayName,
    });

  if (backend) {
    const prepareStart = Date.now();
    await ensureModel({
      backend,
      kind: "embed",
      allowPull: true,
      onProgress: (progress) => {
        send({
          type: "prepare",
          status: "running",
          provider: backend.provider,
          model: backend.embedModel,
          kind: "embed",
          message: progress.status,
          completed: progress.completed,
          total: progress.total,
          determinate: progress.determinate,
        });
      },
    }).then((result) => {
      send({
        type: "prepare",
        status: "complete",
        provider: backend.provider,
        model: result.model,
        kind: "embed",
        downloaded: result.downloaded,
        latencyMs: Date.now() - prepareStart,
      });
    });
  }

  const total = rows.length;
  let processed = 0;

  send({
    type: "start",
    total,
    filename,
    collection,
    useVectorize: collectionConfig.useVectorize,
    provider: backendHint.provider,
    model: backendHint.model,
  });

  for (let index = 0; index < rows.length; index += CSV_BATCH_SIZE) {
    const batch = rows.slice(index, index + CSV_BATCH_SIZE);
    const texts = batch.map((row) =>
      Object.entries(row)
        .map(([key, value]) => `${key}: ${value}`)
        .join("; ")
    );

    const docs = collectionConfig.useVectorize
      ? batch.map((row, batchIndex) => ({
          ...row,
          $vectorize: texts[batchIndex],
          _filename: filename,
          _ingested_at: new Date().toISOString(),
        }))
      : await (async () => {
          if (!backend) {
            throw new Error("AI backend is required for non-vectorize collections");
          }
          const embeddings = (
            await embedMany({
              backend,
              input: texts,
              allowPull: false,
              skipEnsure: true,
            })
          ).embeddings;

          validateVectorDimension({
            collection,
            expected: collectionConfig.vectorDimension,
            embeddings,
          });

          return batch.map((row, batchIndex) => ({
            ...row,
            $vector: embeddings[batchIndex],
            _filename: filename,
            _ingested_at: new Date().toISOString(),
          }));
        })();

    recordAstraClientCall({
      label: "Ingest CSV Batch",
      code: buildTsCall(`db.collection(${JSON.stringify(collection)})`, [
        formatTsMethodCall("insertMany", [
          rawTs(`rowsBatch /* ${docs.length} rows */`),
        ]),
      ]),
    });
    await collectionRef.insertMany(docs);
    processed += batch.length;
    send({ type: "progress", processed, total });
  }

  send({
    type: "complete",
    processed,
    total,
    provider: backendHint.provider,
    model: backendHint.model,
  });
}
